parameters.jsCode:
const event = $('Webhook alerte').first().json;
const expectedSecret = $env.N8N_WEBHOOK_SECRET;
const suppliedSecret = event.headers?.['x-webhook-secret'] ?? event.headers?.['X-Webhook-Secret'];
if (!expectedSecret || suppliedSecret !== expectedSecret) throw new Error('Webhook authentication failed');
const body = event.body ?? {};
const cfg = {};
for (const it of $input.all()) if (it.json && it.json.cle) cfg[it.json.cle] = it.json.valeur;
const seuilLu = Number.parseFloat(cfg.seuil_alerte);
const seuil = Number.isFinite(seuilLu) ? seuilLu : 0.8;
const flag = (v) => (v === undefined || v === null ? true : String(v).toLowerCase() === 'true');
const destinataire = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cfg.notif_email_destinataire || '') ? cfg.notif_email_destinataire : null;
const canalSlack = (typeof cfg.notif_slack_canal === 'string' && /^#[a-z0-9\-]{1,80}$/.test(cfg.notif_slack_canal)) ? cfg.notif_slack_canal : '#alertes-fraude';
const RE = { facture: /^FAC-\d{8}$/, assure: /^ASS-[0-9A-F]{10}$/, prestataire: /^PRE-\d{5}$/, variable: /^[A-Za-z0-9_.\-]{1,60}$/, regle: /^[A-Z_]{3,60}$/, severite: /^(info|moyenne|haute)$/, version: /^\d{1,6}$/ };
const erreurs = [];
const pick = (re, v, nom) => { if (typeof v === 'string' && re.test(v)) return v; erreurs.push(nom); return null; };
const facture = pick(RE.facture, body.facture_id, 'facture_id');
const assure = pick(RE.assure, body.assure_id, 'assure_id');
const prestataire = pick(RE.prestataire, body.prestataire_id, 'prestataire_id');
const score = typeof body.score === 'number' ? body.score : Number.NaN;
if (!(score >= 0 && score <= 1)) erreurs.push('score');
const version = typeof body.version_modele === 'string' && RE.version.test(body.version_modele) ? body.version_modele : null;
const montant = Number.isInteger(body.montant_total) && body.montant_total >= 0 ? String(body.montant_total).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') : null;
const shap = (Array.isArray(body.shap) ? body.shap : []).filter((s) => s && typeof s.variable === 'string' && RE.variable.test(s.variable) && typeof s.contribution === 'number' && Number.isFinite(s.contribution)).slice(0, 5).map((s) => `${s.variable} (${s.contribution >= 0 ? '+' : ''}${s.contribution.toFixed(2).replace('.', ',')})`);
const regles = (Array.isArray(body.regles) ? body.regles : []).filter((r) => r && typeof r.regle_code === 'string' && RE.regle.test(r.regle_code) && typeof r.severite === 'string' && RE.severite.test(r.severite)).slice(0, 5).map((r) => `${r.regle_code} (${r.severite})`);
const codes = (Array.isArray(body.codes_fraude) ? body.codes_fraude : []).filter((code) => typeof code === 'string' && RE.regle.test(code)).slice(0, 14);
const fmt = (x) => x.toFixed(2).replace('.', ',');
const lignes = [`Facture : ${facture}`, `Assuré (pseudonyme) : ${assure}`, `Prestataire : ${prestataire}`, `Score : ${Number.isFinite(score) ? fmt(score) : '?'} (seuil ${fmt(seuil)})`];
if (montant) lignes.push(`Montant : ${montant} MGA`);
if (shap.length) lignes.push(`Variables SHAP principales : ${shap.join(', ')}`);
if (codes.length) lignes.push(`Codes fraude : ${codes.join(', ')}`);
if (regles.length) lignes.push(`Contrôles complémentaires : ${regles.join(', ')}`);
if (version) lignes.push(`Modèle : version ${version}`);
const pied = "Identité de l'assuré : visible uniquement dans PrediCare (rôle gestionnaire).";
const text_slack = `:rotating_light: *Alerte fraude potentielle*\n${lignes.join('\n')}\n_${pied}_`;
const subject = `[PrediCare] Alerte fraude ${facture} (score ${Number.isFinite(score) ? fmt(score) : '?'})`;
const body_email = `Alerte fraude potentielle\n\n${lignes.join('\n')}\n\n${pied}\n`;
const PII = [/[^\s@]+@[^\s@]+\.[^\s@]+/, /(?:\+?261|\b0)\s?3[2-9][\d .]{7,}/, /\b\d{12}\b/];
const pii = PII.some((re) => re.test(text_slack) || re.test(body_email));
let raison = 'ok';
if (erreurs.length) raison = 'payload_invalide'; else if (pii) raison = 'donnees_personnelles_detectees'; else if (!(score >= seuil)) raison = 'sous_seuil';
return [{ json: { envoyer: raison === 'ok', raison, erreurs, facture_id: facture, assure_id: assure, prestataire_id: prestataire, prediction_id: Number.isInteger(body.prediction_id) ? body.prediction_id : null, version_modele: version, score: Number.isFinite(score) ? score : null, seuil, notif_slack: flag(cfg.notif_slack), notif_email: flag(cfg.notif_email) && destinataire !== null, destinataire, canal_slack: canalSlack, text_slack, subject, body_email } }];

