    email_tente: $('Préparer le message (pseudonymes)').first().json.notif_email,
    slack_ok: !!(($('Envoyer Slack').first()?.json) ?? {}).ok,
    email_ok: !!(($('Envoyer Email (Gmail)').first()?.json) ?? {}).id,
